// ─── File: CreationalDemo.java ───
package com.bank.creational;

import java.math.BigDecimal;
import java.util.logging.*;

public class CreationalDemo {
    private static final Logger log = Logger.getLogger(CreationalDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // FACTORY METHOD: pick one product
        SettlementStrategy strategy = SettlementFactory.create(TradeType.EQUITY);
        log.info(() -> "Factory produced: " + strategy.getClass().getSimpleName());

        // ABSTRACT FACTORY: pick a matching family
        ReportKitFactory kit = new RegulatoryKitFactory();
        log.info(() -> "Kit header=" + kit.header() + " formatter=" + kit.formatter());

        // BUILDER: assemble a complex order step by step
        Order order = Order.builder()
            .orderId("ORD-1001")
            .accountId("SAV2001")
            .symbol("RELIANCE")
            .quantity(100)
            .price(new BigDecimal("2450.50"))
            .fee(new BigDecimal("50.00"))
            .build();
        log.info(() -> "Built order: " + order);

        // PROTOTYPE: clone a standard template, tweak a few fields
        OrderTemplate template = new OrderTemplate("NSE", new BigDecimal("0.0010"));
        OrderTemplate rajeshOrder = template.copy();
        rajeshOrder.setSymbol("TCS");
        rajeshOrder.setQuantity(25);
        log.info(() -> "Prototype clone: " + rajeshOrder + " (original unchanged: " + template + ")");
    }
}

enum TradeType { EQUITY, FX }

// ─── FACTORY METHOD ───
interface SettlementStrategy { void settle(); }
class EquitySettlement implements SettlementStrategy {
    public void settle() { Logger.getLogger("SETTLE").info("Equity settled T+1"); }
}
class SettlementFactory {
    static SettlementStrategy create(TradeType type) {
        return switch (type) {
            case EQUITY -> new EquitySettlement();
            default -> throw new IllegalArgumentException("No handler: " + type);
        };
    }
}

// ─── ABSTRACT FACTORY: a family of matching products ───
interface ReportKitFactory { String header(); String footer(); String formatter(); }
class RegulatoryKitFactory implements ReportKitFactory {
    public String header() { return "RBI-REGULATORY-HEADER"; }
    public String footer() { return "RBI-REGULATORY-FOOTER"; }
    public String formatter() { return "XBRL-FORMATTER"; }
}

// ─── BUILDER: solves telescoping constructor, returns immutable Order ───
class Order {
    private final String orderId, accountId, symbol;
    private final int quantity;
    private final BigDecimal price, fee;
    private Order(Builder b) {
        this.orderId=b.orderId; this.accountId=b.accountId; this.symbol=b.symbol;
        this.quantity=b.quantity; this.price=b.price; this.fee=b.fee;
    }
    static Builder builder() { return new Builder(); }
    public String toString() {
        return orderId + " " + accountId + " " + symbol + " x" + quantity + " @" + price + " fee=" + fee;
    }
    static class Builder {
        private String orderId, accountId, symbol;
        private int quantity;
        private BigDecimal price, fee = BigDecimal.ZERO;
        Builder orderId(String v){this.orderId=v;return this;}
        Builder accountId(String v){this.accountId=v;return this;}
        Builder symbol(String v){this.symbol=v;return this;}
        Builder quantity(int v){this.quantity=v;return this;}
        Builder price(BigDecimal v){this.price=v;return this;}
        Builder fee(BigDecimal v){this.fee=v;return this;}
        Order build() {
            if (orderId==null||symbol==null) throw new IllegalStateException("orderId and symbol required");
            return new Order(this);
        }
    }
}

// ─── PROTOTYPE: copy constructor based cloning (safer than Cloneable) ───
class OrderTemplate {
    private final String exchange;
    private final BigDecimal defaultFeeRate;
    private String symbol;
    private int quantity;
    OrderTemplate(String exchange, BigDecimal feeRate) { this.exchange=exchange; this.defaultFeeRate=feeRate; }
    // copy constructor used by copy()
    private OrderTemplate(OrderTemplate o) {
        this.exchange=o.exchange; this.defaultFeeRate=o.defaultFeeRate;
        this.symbol=o.symbol; this.quantity=o.quantity;
    }
    OrderTemplate copy() { return new OrderTemplate(this); }
    void setSymbol(String s){this.symbol=s;} void setQuantity(int q){this.quantity=q;}
    public String toString() { return exchange+" rate="+defaultFeeRate+" sym="+symbol+" qty="+quantity; }
}

class BankLogFormatter extends Formatter {
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
